def magic_square_test(matrix):
    n = len(matrix)
    row_sum = sum(matrix[0])
    col_sum = sum(matrix[i][0] for i in range(n))
    diag1_sum = sum(matrix[i][i] for i in range(n))
    diag2_sum = sum(matrix[i][n-1-i] for i in range(n))
    for i in range(n):
        if sum(matrix[i]) != row_sum:
            return False
    for j in range(n):
        if sum(matrix[i][j] for i in range(n)) != row_sum:
            return False
    if diag1_sum != row_sum or diag2_sum != row_sum:
        return False
    if row_sum != 0:
        return True
    return False
