def pancake_sort(arr):
    def flip(arr, k):
        arr[:k+1] = arr[:k+1][::-1]
    n = len(arr)
    for i in range(n, 1, -1):
        max_idx = 0
        for j in range(1, i):
            if arr[j] > arr[max_idx]:
                max_idx = j
        if max_idx != i - 1:
            flip(arr, max_idx)
            flip(arr, i - 1)
    return arr
